#requires -Version 5.1
<# Standalone installer. Python 3.8+ required. Git only for submodule mode. #>
[CmdletBinding()]
param(
    [string]$Project,
    [string]$Version,
    [string]$Directory,
    [ValidateSet('submodule', 'source')][string]$Mode,
    [ValidateSet('pack', 'github-zip')][string]$Format,
    [string]$Archive,
    [string]$Sha256,
    [string]$Target,
    [string]$Repository,
    [switch]$NonInteractive,
    [switch]$ListVersions,
    [switch]$Help
)
$ErrorActionPreference = 'Stop'
$forward = @()
foreach ($name in @('Project', 'Version', 'Directory', 'Mode', 'Format', 'Archive', 'Sha256', 'Target', 'Repository')) {
    if ($PSBoundParameters.ContainsKey($name)) {
        $forward += '--' + $name.ToLowerInvariant()
        $forward += [string]$PSBoundParameters[$name]
    }
}
if ($NonInteractive) { $forward += '--non-interactive' }
if ($ListVersions) { $forward += '--list-versions' }
if ($Help) { $forward += '--help' }
$pythonCommand = $null
$pythonPrefix = @()
foreach ($candidate in @('py', 'python3', 'python')) {
    if (Get-Command $candidate -ErrorAction SilentlyContinue) {
        $prefix = @()
        if ($candidate -eq 'py') { $prefix = @('-3') }
        & $candidate @prefix -c 'import sys;sys.exit(0 if sys.version_info >= (3,8) else 1)' 2>$null
        if ($LASTEXITCODE -eq 0) {
            $pythonCommand = $candidate
            $pythonPrefix = $prefix
            break
        }
    }
}
if (-not $pythonCommand) { throw 'Python 3.8+ is required. Install Python and add it to PATH, then retry.' }
$loader = 'import base64,zlib;exec(compile(zlib.decompress(base64.b64decode('''')),''stm32-rtt-installer'',''exec''))'
& $pythonCommand @pythonPrefix -c $loader @forward
if ($LASTEXITCODE -ne 0) { throw "stm32-rtt failed (exit $LASTEXITCODE)." }
